class WorkQueue {
public:
    using Job = std::function<void()>;
    void push(Job job);
    [[nodiscard]] bool runOne();
    void close();
private:
    std::mutex mutex_;
    std::condition_variable ready_;
    std::queue<Job> jobs_;
    bool closed_ = false;
};

